package org.eclipse.rdf4j.opentelemetry.repository;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockserver.model.HttpRequest.request;
import static org.mockserver.model.HttpResponse.response;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.List;

import org.eclipse.rdf4j.opentelemetry.OpenTelemetrySupport;
import org.eclipse.rdf4j.opentelemetry.RDF4JOpenTelemetryConfig;
import org.eclipse.rdf4j.repository.Repository;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.http.HTTPRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.RDFWriter;
import org.eclipse.rdf4j.rio.Rio;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.extension.RegisterExtension;
import org.mockserver.client.MockServerClient;
import org.mockserver.junit.jupiter.MockServerExtension;
import org.mockserver.model.MediaType;

import io.opentelemetry.sdk.testing.junit5.OpenTelemetryExtension;
import io.opentelemetry.sdk.trace.data.SpanData;

/**
 * Regression coverage for the passthrough fast path in {@code SPARQLProtocolSession.getRDF(...)}: if the supplied
 * {@link org.eclipse.rdf4j.rio.RDFHandler} is a {@code ByteSink}/{@code CharSink} (as every Rio {@code RDFWriter} is),
 * the HTTP response body is copied directly into the writer's stream, bypassing parsing (and the strict datatype
 * validation that parsing applies) entirely. {@link TracingRepositoryConnection#exportStatements} must not break this
 * by wrapping the handler in something that no longer looks like a {@code Sink}.
 */
@ExtendWith(MockServerExtension.class)
class TracingRepositoryConnectionExportPassthroughTest {

	@RegisterExtension
	static final OpenTelemetryExtension otelTesting = OpenTelemetryExtension.create();

	private HTTPRepository httpRepository;

	@AfterEach
	void tearDown() {
		if (httpRepository != null) {
			httpRepository.shutDown();
		}
	}

	@Test
	void exportStatements_preservesPassthroughForStrictlyInvalidButSyntacticallyLegalData(MockServerClient client)
			throws Exception {
		// a literal that is syntactically legal Turtle but fails strict datatype verification if actually parsed;
		// HTTPRepositoryConnection enables strict datatype verification (VERIFY_DATATYPE_VALUES) by default
		String turtleBody = "<urn:s> <urn:p> \"not-an-integer\"^^<http://www.w3.org/2001/XMLSchema#integer> .\n";
		client.when(request().withPath(".*/protocol"))
				.respond(response().withStatusCode(200).withBody("13", MediaType.parse("text/plain")));
		client.when(request().withPath(".*/statements"))
				.respond(response().withStatusCode(200)
						.withBody(turtleBody, MediaType.parse("text/turtle")));

		httpRepository = new HTTPRepository("http://localhost:" + client.getPort() + "/repositories/test-repo");
		httpRepository.init();

		Repository traced = OpenTelemetrySupport.instrument(httpRepository, "test-repo",
				RDF4JOpenTelemetryConfig.builder().openTelemetry(otelTesting.getOpenTelemetry()).build());

		ByteArrayOutputStream out = new ByteArrayOutputStream();
		try (RepositoryConnection conn = traced.getConnection()) {
			RDFWriter writer = Rio.createWriter(RDFFormat.TURTLE, out);
			// must not throw: passthrough bypasses parsing, so strict datatype verification never runs
			conn.exportStatements(null, null, null, true, writer);
		}

		assertThat(out.toString(StandardCharsets.UTF_8)).contains("not-an-integer");

		// no row count is available: the response bypassed our counting handler entirely via passthrough
		List<SpanData> spans = otelTesting.getSpans();
		assertThat(spans).hasSize(1);
		assertThat(spans.get(0).getAttributes().get(DbOtelAttributes.DB_RESPONSE_RETURNED_ROWS)).isNull();
	}
}
